import React, { useState } from 'react';
import './App.css';

export type Camera = 'lobby' | 'garage' | 'roof';

export interface Frame {
  /** 1-based position in the recording. */
  index: number;
  /** When the still was taken, as an ISO time in UTC. */
  takenAt: string;
  /** An image of the still. */
  src: string;
}

/** How long each still stays on screen while playing, in milliseconds. */
export const FRAME_MS = 200;

/** Minutes between stills: uneven, as a camera that shoots on motion takes them. */
const GAPS_MIN = [5, 12, 7, 15, 9, 6, 11, 14, 8, 10, 13, 5, 7, 12, 9];
const FIRST_SHOT = Date.UTC(2026, 2, 14, 8, 0);

function stillImage(index: number, time: string): string {
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180">'
    + '<rect width="320" height="180" fill="#1f2937"/>'
    + `<text x="160" y="84" fill="#f9fafb" font-family="sans-serif" font-size="28" text-anchor="middle">Frame ${index}</text>`
    + `<text x="160" y="120" fill="#9ca3af" font-family="sans-serif" font-size="18" text-anchor="middle">${time} UTC</text>`
    + '</svg>';
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

/** The lobby camera's sixteen stills, oldest first. */
export const FRAMES: Frame[] = [0, ...GAPS_MIN].reduce<Frame[]>((frames, gap, i) => {
  const previous = frames[i - 1];
  const takenAt = new Date((previous ? Date.parse(previous.takenAt) : FIRST_SHOT) + gap * 60000).toISOString();
  return [...frames, { index: i + 1, takenAt, src: stillImage(i + 1, takenAt.slice(11, 16)) }];
}, []);

/** "08:05": the time of day a still was taken, in UTC. */
export function timeLabel(frame: Frame): string {
  return frame.takenAt.slice(11, 16);
}

/**
 * The camera API: the lobby's stills, none for the garage and an error for the roof camera. The garage answers after
 * 150 ms and the others after 400 ms, so an answer can arrive after the camera has changed.
 */
export function fetchFrames(camera: Camera): Promise<Frame[]> {
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (camera === 'roof') reject(new Error('The roof camera is offline'));
      else resolve(camera === 'lobby' ? FRAMES : []);
    }, camera === 'garage' ? 150 : 400);
  });
}

export default function App() {
  const [camera, setCamera] = useState<Camera>('lobby');
  const frame = FRAMES[0];

  // TODO Task 1: load the stills of `camera` with `fetchFrames`, on mount and whenever the camera changes, and show
  // one state at a time: `Loading frames…` in `.status--loading`, `Could not load frames` in `.status--error` with a
  // `.retry` button, `No frames for this camera` in `.empty`, or the current still with `.position` and `.time`. An
  // answer for a camera that is no longer selected must not show.
  // TODO Task 2: add the `.toggle` button: Play, Pause and Replay, one still every `FRAME_MS` milliseconds.
  // TODO Task 3: add the `.timeline` of `.marker` buttons and the `.scrubber` range input under the still.
  // TODO Task 4: step with ArrowLeft and ArrowRight and play or pause with Space on `.player`, and leave no timer
  // running behind.

  return (
    <main className="player" aria-label="Camera stills">
      <header className="bar">
        <label className="camera-field">
          Camera
          <select className="camera" value={camera} onChange={(event) => setCamera(event.target.value as Camera)}>
            <option value="lobby">Lobby</option>
            <option value="garage">Garage</option>
            <option value="roof">Roof</option>
          </select>
        </label>
      </header>

      <figure className="viewer">
        <img className="frame" src={frame.src} alt="A still from the lobby camera" />
      </figure>
    </main>
  );
}

files.src/App.css:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #111827;
  background: #f3f4f6;
}

.player {
  display: grid;
  gap: 12px;
  max-width: 560px;
  margin: 24px auto;
  padding: 16px;
  border: 1px solid #d1d5db;
  border-radius: 12px;
  background: #ffffff;
}

.player:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

.bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.camera-field {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.camera {
  min-height: 36px;
  padding: 4px 8px;
  font: inherit;
}

.status,
.empty {
  margin: 0;
  padding: 12px;
  border-radius: 8px;
  background: #f9fafb;
}

.status--error {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: #991b1b;
  background: #fef2f2;
}

.viewer {
  margin: 0;
}

.frame {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  background: #1f2937;
}

.caption {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  margin-top: 8px;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.toggle,
.retry {
  min-height: 36px;
  min-width: 80px;
  padding: 6px 14px;
  border: 1px solid #1d4ed8;
  border-radius: 8px;
  font: inherit;
  color: #ffffff;
  background: #2563eb;
  cursor: pointer;
}

.scrubber {
  flex: 1;
  min-width: 0;
}

.timeline {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.marker {
  width: 16px;
  height: 16px;
  padding: 0;
  border: 2px solid #6b7280;
  border-radius: 50%;
  background: #ffffff;
  cursor: pointer;
}

.marker[aria-current='true'] {
  border-color: #1d4ed8;
  background: #2563eb;
}
